<script setup lang="ts">
import { computed, ref, watchEffect } from 'vue';
import { field, types, validate, parse, type Config, type Kind } from './model';
import { html, react } from './export';
import { download, readFile, message } from './io';
import FieldPreview from './FieldPreview.vue'; import FieldEditor from './FieldEditor.vue';
const config = ref<Config>({ version: 1, title: 'Form baru', fields: [] });
const selected = ref(''), status = ref(''), result = ref(''), mode = ref('html');
const dark = ref(localStorage.getItem('theme') === 'dark');
watchEffect(() => { document.documentElement.dataset.theme = dark.value ? 'dark' : 'light'; localStorage.setItem('theme', dark.value ? 'dark' : 'light'); });
const active = computed(() => config.value.fields.find(f => f.id === selected.value));
const code = computed(() => { try { return mode.value === 'html' ? html(config.value) : react(config.value); } catch (e) { return message(e); } });
const error = computed(() => { try { validate(config.value); return ''; } catch (e) { return message(e); } });
let next = 1;
function add(type: Kind) { const f = field(type, next++); while (config.value.fields.some(x => x.name === f.name)) f.name = 'field_' + next++; config.value.fields.push(f); selected.value = f.id; }
function reorder(index: number, delta: number) { const target = index + delta; if (target < 0 || target >= config.value.fields.length) return; const [f] = config.value.fields.splice(index, 1); config.value.fields.splice(target, 0, f); }
function drop(event: DragEvent, index?: number) { const data = event.dataTransfer?.getData('text/plain') || ''; if (data.startsWith('type:') && types.includes(data.slice(5) as Kind)) add(data.slice(5) as Kind); if (data.startsWith('index:') && index !== undefined) { const from = +data.slice(6); if (Number.isInteger(from) && from >= 0 && from < config.value.fields.length) reorder(from, index - from); } }
function save() { try { validate(config.value); localStorage.setItem('form-config', JSON.stringify(config.value)); status.value = 'Form disimpan di browser ini.'; } catch (e) { status.value = message(e); } }
function open() { try { config.value = parse(localStorage.getItem('form-config') || ''); selected.value = ''; status.value = 'Form dibuka.'; } catch (e) { status.value = message(e); } }
async function importFile(event: Event) { try { config.value = parse(await readFile((event.target as HTMLInputElement).files?.[0])); selected.value = ''; } catch (e) { status.value = message(e); } }
function submit(event: Event) { result.value = JSON.stringify(Object.fromEntries(new FormData(event.target as HTMLFormElement)), null, 2); }
</script>
<template><header><span class="brand"><b>04</b>DEVELOPER / TOOLS</span><div class="row"><span class="pill">RUANG KERJA LOKAL</span><button aria-label="Ganti tema" @click="dark = !dark">{{ dark ? 'Terang' : 'Gelap' }}</button></div></header><main><div class="intro"><div><div class="eyebrow">Alat pengembangan · 04 / 10</div><h1>Form Builder</h1><p>Rancang form, tetapkan aturan validasi, dan bawa kode yang berfungsi ke proyek Anda.</p></div><span class="tag">DIBUAT UNTUK BEKERJA.</span></div>
<div v-if="status" class="status" role="status">{{ status }}</div><div class="toolbar"><label>Judul form<input v-model="config.title"></label><button @click="save">Simpan lokal</button><button @click="open">Buka tersimpan</button><button :disabled="!!error" @click="download('form.json', JSON.stringify(config, null, 2), 'application/json')">Export JSON</button><label class="file">Import konfigurasi<input type="file" accept=".json" @change="importFile"></label></div>
<div class="builder-grid"><section class="panel"><div class="panel-head"><h2>Komponen & struktur</h2></div><div class="panel-body stack"><small>Geser komponen ke area struktur atau klik untuk menambah.</small><div class="palette"><button v-for="type in types" :key="type" draggable="true" @dragstart="$event.dataTransfer?.setData('text/plain','type:' + type)" @click="add(type)">+ {{ type }}</button></div><div class="drop-zone stack" @dragover.prevent @drop.prevent="drop($event)"><p v-if="!config.fields.length" class="muted">Letakkan komponen di sini.</p><div v-for="(f,index) in config.fields" :key="f.id" class="field-item" :class="{ selected: f.id === selected }" draggable="true" @dragstart="$event.dataTransfer?.setData('text/plain','index:' + index)" @dragover.prevent @drop.stop.prevent="drop($event,index)"><button class="field-select" @click="selected = f.id">{{ index + 1 }}. {{ f.label }} <small>{{ f.type }}</small></button><div class="row"><button aria-label="Naik" @click="reorder(index,-1)">↑</button><button aria-label="Turun" @click="reorder(index,1)">↓</button><button class="danger" @click="config.fields.splice(index,1)">Hapus</button></div></div></div></div></section>
<section class="panel"><div class="panel-head"><h2>Properti field</h2></div><div class="panel-body"><FieldEditor v-if="active" :field="active" /><div v-else class="empty">Pilih field untuk mengatur label dan validasinya.</div></div></section>
<div class="stack"><section class="panel"><div class="panel-head"><h2>Live preview</h2><span class="pill">FORM AKTIF</span></div><div class="panel-body"><form class="stack" @submit.prevent="submit"><h3>{{ config.title }}</h3><FieldPreview v-for="f in config.fields" :key="f.id" :field="f" /><button v-if="config.fields.length" class="primary" type="submit">Uji kirim</button><p v-else class="empty">Tambahkan field untuk mencoba form.</p></form><pre v-if="result">{{ result }}</pre></div></section>
<section class="panel"><div class="panel-head"><h2>Kode form</h2><select v-model="mode" aria-label="Format export"><option value="html">HTML mandiri</option><option value="react">React TSX</option></select><button :disabled="!!error" @click="download(mode === 'html' ? 'form.html' : 'GeneratedForm.tsx', code)">Download</button></div><div v-if="error" class="status" role="alert">{{ error }}</div><pre v-else>{{ code }}</pre></section></div></div><footer class="note"><span>Form Builder / AhmadNurHidayat-23</span><span>Data diproses di perangkat Anda.</span></footer></main></template>
